package com.chatsystem.user.controller.social;
import com.chatsystem.shared.mock.MockFixtures;
import com.chatsystem.user.*;
import com.chatsystem.user.navigation.*;
import javafx.scene.Node;import javafx.scene.control.*;import javafx.stage.Stage;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class SocialWorkflowControllerTest extends JavaFxTestSupport{
 @Test void searchMessageBlockAndUnblockStayConsistent() throws Exception{onFx(()->{var c=new UserApplicationContext();assertTrue(c.auth().login(MockFixtures.DEMO_EMAIL,MockFixtures.DEMO_PASSWORD,false).isSuccess());var s=new Stage();try{var n=new UserNavigator(s,c);n.start();n.navigate(ViewRequest.of(UserRoute.FRIENDS));ListView<?> list=(ListView<?>)node(s,"friendList");assertEquals(3,list.getItems().size());((TextField)node(s,"friendSearchField")).setText("Mia");assertEquals(1,list.getItems().size());list.getSelectionModel().selectFirst();((Button)node(s,"messageFriendButton")).fire();assertEquals(UserRoute.CHAT_PRIVATE,n.currentRequest().route());n.navigate(ViewRequest.of(UserRoute.FRIENDS));list=(ListView<?>)node(s,"friendList");list.getSelectionModel().selectFirst();((Button)node(s,"blockUserButton")).fire();assertEquals(2,c.social().getFriends().size());n.navigate(ViewRequest.of(UserRoute.BLOCKED_USERS));ListView<?> blocked=(ListView<?>)node(s,"blockedList");assertEquals(2,blocked.getItems().size());blocked.getSelectionModel().selectFirst();((Button)node(s,"unblockButton")).fire();assertEquals(1,c.social().getBlockedUsers().size());}finally{s.close();}});}
 @Test void requestActionsAndInvalidAddHaveObservableResults() throws Exception{onFx(()->{var c=new UserApplicationContext();c.auth().login(MockFixtures.DEMO_EMAIL,MockFixtures.DEMO_PASSWORD,false);var s=new Stage();try{var n=new UserNavigator(s,c);n.start();n.navigate(ViewRequest.of(UserRoute.FRIEND_REQUESTS));ListView<?> incoming=(ListView<?>)node(s,"incomingList");incoming.getSelectionModel().selectFirst();((Button)node(s,"acceptButton")).fire();assertTrue(c.social().getIncomingRequests().isEmpty());assertEquals(4,c.social().getFriends().size());n.navigate(ViewRequest.of(UserRoute.FRIENDS));int before=c.social().getOutgoingRequests().size();((TextField)node(s,"addFriendField")).setText("1");((Button)node(s,"addFriendButton")).fire();assertEquals(before,c.social().getOutgoingRequests().size());assertFalse(((Label)node(s,"socialFeedbackLabel")).getText().isBlank());((TextField)node(s,"addFriendField")).setText("10");((Button)node(s,"addFriendButton")).fire();assertEquals(before+1,c.social().getOutgoingRequests().size());}finally{s.close();}});}
 private static Node node(Stage s,String id){Node n=s.getScene().getRoot().lookup("#"+id);assertNotNull(n,id);return n;}
}
